import React, { useState, useEffect } from "react";

export default function History() {
  const [history, setHistory] = useState([]);

  useEffect(() => {
    const stored = localStorage.getItem("predictionHistory");
    if (stored) {
      setHistory(JSON.parse(stored));
    }
  }, []);

  const clearHistory = () => {
    localStorage.removeItem("predictionHistory");
    setHistory([]);
  };

  return (
    <div style={container}>
      <div style={header}>
        <h2 style={{ margin: 0 }}>Prediction History</h2>

        {history.length > 0 && (
          <button onClick={clearHistory} style={clearBtn}>
            Clear History
          </button>
        )}
      </div>

      {history.length === 0 ? (
        <div style={emptyState}>
          No predictions yet. Go to the Predict page to make one.
        </div>
      ) : (
        <div style={tableWrapper}>
          <table style={table}>
            <thead>
              <tr style={thead}>
                <th style={th}>Industry</th>
                <th style={th}>Country</th>
                <th style={th}>Company Age</th>
                <th style={th}>Avg Size</th>
                <th style={th}>Current Employees</th>
                <th style={th}>Total Employees</th>
                <th style={th}>Model Type</th>
                <th style={th}>Cluster</th>
                <th style={th}>Prediction</th>
                <th style={th}>Confidence</th>
              </tr>
            </thead>

            <tbody>
              {history.map((item, idx) => (
                <tr key={idx} style={row}>
                  <td style={td}>{item.industry_enc}</td>
                  <td style={td}>{item.country_enc}</td>
                  <td style={td}>{item.company_age}</td>
                  <td style={td}>{item.avg_size}</td>
                  <td style={td}>{item.current_employee_estimate}</td>
                  <td style={td}>{item.total_employee_estimate}</td>
                  <td style={td}>{item.model_type}</td>
                  <td style={td}>{item.result?.cluster || "-"}</td>
                  <td style={td}>{item.result?.prediction || "-"}</td>
                  <td style={td}>
                    {item.result?.confidence != null
                      ? (item.result.confidence * 100).toFixed(2) + "%"
                      : "-"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

/* ---------- Styles ---------- */

const container = {
  width: "100%",
  height: "100%",
  display: "flex",
  flexDirection: "column",
  gap: "20px"
};

const header = {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center"
};

const clearBtn = {
  padding: "10px 18px",
  background: "#f44336",
  color: "white",
  border: "none",
  borderRadius: "6px",
  fontWeight: "600",
  cursor: "pointer"
};

const emptyState = {
  padding: "60px",
  textAlign: "center",
  color: "#666",
  background: "#fafafa",
  borderRadius: "10px"
};

const tableWrapper = {
  width: "100%",
  overflowX: "auto"
};

const table = {
  width: "100%",
  borderCollapse: "collapse"
};

const thead = {
  background: "#4CAF50",
  color: "white"
};

const th = {
  padding: "12px",
  textAlign: "center",
  fontWeight: "600"
};

const td = {
  padding: "10px",
  textAlign: "center",
  borderBottom: "1px solid #eee"
};

const row = {
  background: "white"
};
